// ============================================
// NODE 3 — QUIZ RELEASE + REMINDER + ESCALATION
// Sesuai spec: 3-stage reminder dengan state machine
// ============================================

const assignments = $input.all();
const now = new Date();

const quizToSend     = [];
const reminderToSend = [];
const toEscalate     = [];

for (const item of assignments) {
  const f = item.json.fields;

  const assignedDate = new Date(f.assigned_date);
  const dueDate      = new Date(f.due_date);
  const quizSentDate = f.quiz_sent_date ? new Date(f.quiz_sent_date) : null;

  const ageInDays        = diffDays(now, assignedDate);
  const daysSinceQuiz    = quizSentDate ? diffDays(now, quizSentDate) : null;
  const daysUntilDue     = diffDays(dueDate, now); // positif = belum due
  const isOverdue        = now > dueDate;
  const reminderCount    = f.reminder_count || 0;

  // --------------------------
  // QUIZ RELEASE
  // status=Assigned, quiz_sent=false, umur >= 7 hari
  // --------------------------
  if (
    f.status === 'Assigned' &&
    !f.quiz_sent &&
    ageInDays >= 7
  ) {
    quizToSend.push(buildItem('send_quiz', item, f, { dueDate }));
    continue;
  }

  // --------------------------
  // ESCALATION (cek sebelum reminder — prioritas tertinggi)
  // status=In Progress, due_date sudah lewat
  // --------------------------
  if (
    f.status === 'In Progress' &&
    isOverdue
  ) {
    toEscalate.push(buildItem('escalate', item, f, {
      dueDate,
      days_overdue: Math.floor(diffDays(now, dueDate))
    }));
    continue;
  }

  // --------------------------
  // REMINDER 1
  // reminder_count=0, today >= quiz_sent_date + 3
  // --------------------------
  if (
    f.status === 'In Progress' &&
    f.quiz_sent === true &&
    reminderCount === 0 &&
    daysSinceQuiz !== null &&
    daysSinceQuiz >= 3
  ) {
    reminderToSend.push(buildItem('reminder_1', item, f, {
      dueDate,
      reminder_number: 1,
      next_reminder_count: 1,
      message_context: `Quiz belum dikerjakan. Anda masih punya waktu hingga ${formatDateWIB(dueDate)}.`
    }));
    continue;
  }

  // --------------------------
  // REMINDER 2
  // reminder_count=1, today >= quiz_sent_date + 5
  // --------------------------
  if (
    f.status === 'In Progress' &&
    reminderCount === 1 &&
    daysSinceQuiz !== null &&
    daysSinceQuiz >= 5
  ) {
    reminderToSend.push(buildItem('reminder_2', item, f, {
      dueDate,
      reminder_number: 2,
      next_reminder_count: 2,
      message_context: `Ini pengingat kedua. Deadline semakin dekat.`
    }));
    continue;
  }

  // --------------------------
  // REMINDER 3
  // reminder_count=2, today >= due_date - 1 hari
  // --------------------------
  if (
    f.status === 'In Progress' &&
    reminderCount === 2 &&
    daysUntilDue <= 1 &&
    !isOverdue
  ) {
    reminderToSend.push(buildItem('reminder_3', item, f, {
      dueDate,
      reminder_number: 3,
      next_reminder_count: 3,
      message_context: `⚠️ Deadline besok! Ini pengingat terakhir sebelum eskalasi ke HR.`
    }));
    continue;
  }

}

return [...quizToSend, ...reminderToSend, ...toEscalate];


// ============================================
// HELPERS
// ============================================

function diffDays(laterDate, earlierDate) {
  return (laterDate - earlierDate) / (1000 * 60 * 60 * 24);
}

function formatDateWIB(date) {
  const wib = new Date(date.getTime() + (7 * 60 * 60 * 1000));
  const days   = ['Minggu','Senin','Selasa','Rabu','Kamis','Jumat','Sabtu'];
  const months = ['Januari','Februari','Maret','April','Mei','Juni',
                  'Juli','Agustus','September','Oktober','November','Desember'];
  return `${days[wib.getUTCDay()]}, ${wib.getUTCDate()} ${months[wib.getUTCMonth()]} ${wib.getUTCFullYear()}`;
}

function buildItem(action, item, f, extras = {}) {
  return {
    json: {
      action,
      record_id:      item.json.id,
      assignment_id:  f.assignment_id,
      employee_name:  f['full_name (from employee_id)']?.[0],
      employee_email: f['email (from employee_id)']?.[0]?.trim(),
      module_name:    f['module_name (from module_id)']?.[0],
      module_quiz_url: f['quiz_link (from module_id)']?.[0],
      reminder_count: f.reminder_count || 0,
      due_date_display: extras.dueDate ? formatDateWIB(extras.dueDate) : null,
      ...extras
    }
  };
}

