const items = $input.all();

const stats = {
  quiz: 0,
  reminder1: 0,
  reminder2: 0,
  reminder3: 0,
  escalation: 0
};

const details = [];

for (const item of items) {

  switch(item.json.action) {

    case 'send_quiz':
      stats.quiz++;
      break;

    case 'reminder_1':
      stats.reminder1++;
      break;

    case 'reminder_2':
      stats.reminder2++;
      break;

    case 'reminder_3':
      stats.reminder3++;
      break;

    case 'escalate':
      stats.escalation++;
      break;
  }

  details.push(
`• ${item.json.employee_name}
(${item.json.employee_email})
→ ${item.json.module_name}
[${item.json.action}]`
  );
}

return [{
  json: {
    ...stats,
    total: items.length,
    details: details.join('\n\n')
  }
}];
